import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Performance Meeting 2022-12-08","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-12-08","date":"2022-12-08T00:00:00.000Z","updated":"2022-12-08T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-12-08.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-12-08.md","lastUpdated":1780459816000}'),o={name:"posts/2022/Ceph_Performance_Meeting_2022-12-08.md"};function i(n,e,s,h,u,d){return t(),r("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>Pull Request 审查</strong>: 会议开始时，主持人完成了所有 Pull Request 的审查，并更新了列表。</li><li><strong>RGW 更新</strong>: 讨论了与 d4n 相关的 RGW 更新 PR。</li><li><strong>RocksDB 更新</strong>: 讨论了更新 RocksDB 到最新版本以支持新的压缩选项。</li><li><strong>BlueFS 4K 分配单元</strong>: 提出了 BlueFS 启用 4K 分配单元的 PR，但因相关人员不在场而未深入讨论。</li><li><strong>BlueStore 分配器优化</strong>: 讨论了 BlueStore 中 AVL 和混合分配器加速的 PR。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ul><li><strong>性能优化</strong>: Luke 讨论了优化 Ceph 集群性能的策略，包括使用 RAID 配置和不同存储配置的测试。</li><li><strong>网络和存储配置</strong>: 讨论了网络配置、RAID 级别选择、Erasure Coding 与复制的性能影响，以及如何诊断和优化 RGW 的性能问题。</li><li><strong>硬件和软件配置</strong>: 讨论了硬件 RAID 控制器缓存、网络带宽、OSD 内存目标设置等对性能的影响。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>RocksDB 更新</strong>: 决定考虑更新 RocksDB 到最新版本，但需要先看到测试结果。</li><li><strong>性能测试</strong>: 决定进行一系列性能测试，包括不同 RAID 配置、Erasure Coding 与复制的比较，以及单个磁盘与 RAID 配置的性能对比。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>性能测试</strong>: 进行详细的性能测试，包括不同 RAID 配置和存储策略的测试。</li><li><strong>RGW 优化</strong>: 继续优化 RGW 的配置和性能，特别是在处理大量数据读取时的情况。</li><li><strong>CRC32 优化</strong>: 针对 ARM V8 平台的 CRC32 性能问题，计划创建一个跟踪器并进行进一步的调查和优化。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><strong>大型集群管理</strong>: 讨论了管理大型 Ceph 集群时可能遇到的问题，特别是与管理器和监视器相关的性能问题。</li><li><strong>硬件支持</strong>: 讨论了硬件 RAID 控制器缓存和 SSD 元数据驱动器对性能的影响。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议涵盖了多个关于 Ceph 性能优化和配置的话题，特别是在处理大量数据和高并发读取时的性能问题。后续将进行一系列详细的性能测试和优化工作。</p><h3 id="改进说明" tabindex="-1">改进说明 <a class="header-anchor" href="#改进说明" aria-label="Permalink to &quot;改进说明&quot;">​</a></h3><ol><li>确保了所有关键细节都被包含在总结中，包括 Pull Request 的审查、RGW 和 RocksDB 的更新。</li><li>确保了主要议题、决定事项和后续行动计划都被准确反映。</li><li>添加了对大型集群管理和硬件支持的讨论，这些内容在原始总结中未提及。</li><li>保留了所有相关的 Ceph 和计算机科学领域的英文原文关键词。</li></ol>',15)])])}const _=a(o,[["render",i]]);export{g as __pageData,_ as default};
